<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Document\Template\Domain\TemplateRef;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\ValueObject\TemplateVersionTemplateVO;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\ValueObject\TemplateVersionSubjectVO;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\ValueObject\TemplateVersionContentHtmlVO;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\ValueObject\TemplateVersionContentTextVO;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\ValueObject\TemplateVersionVersionVO;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\TemplateVersionAttributes;
use PHPUnit\Framework\TestCase;

final class TemplateVersionAttributesUnitTest extends TestCase
{
    public function test(): void
    {
        $value = new TemplateVersionAttributes();
        $templateOneValue = new TemplateRef('one');
        $templateOtherValue = new TemplateRef('other');
        $copy = $value->template($templateOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(new TemplateRef('one'), $value->getTemplate());
        $this->assertNotEquals(new TemplateRef('other'), $value->getTemplate());
        $this->assertEquals(new TemplateRef('one'), $value->getTemplateOrCurrent(TemplateVersionTemplateVO::from($templateOtherValue))->value());
        $this->assertNotEquals(new TemplateRef('other'), $value->getTemplateOrCurrent(TemplateVersionTemplateVO::from($templateOtherValue))->value());
        $value->unsetTemplate();
        $this->assertEquals(new TemplateRef('other'), $value->getTemplateOrCurrent(TemplateVersionTemplateVO::from($templateOtherValue))->value());
        $this->assertNotEquals(new TemplateRef('one'), $value->getTemplateOrCurrent(TemplateVersionTemplateVO::from($templateOtherValue))->value());
        $subjectOneValue = 'one';
        $subjectOtherValue = 'other';
        $copy = $value->subject($subjectOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('one', $value->getSubject());
        $this->assertNotEquals('other', $value->getSubject());
        $this->assertEquals('one', $value->getSubjectOrCurrent(TemplateVersionSubjectVO::from($subjectOtherValue))->value());
        $this->assertNotEquals('other', $value->getSubjectOrCurrent(TemplateVersionSubjectVO::from($subjectOtherValue))->value());
        $value->unsetSubject();
        $this->assertEquals('other', $value->getSubjectOrCurrent(TemplateVersionSubjectVO::from($subjectOtherValue))->value());
        $this->assertNotEquals('one', $value->getSubjectOrCurrent(TemplateVersionSubjectVO::from($subjectOtherValue))->value());
        $contentHtmlOneValue = 'one';
        $contentHtmlOtherValue = 'other';
        $copy = $value->contentHtml($contentHtmlOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('one', $value->getContentHtml());
        $this->assertNotEquals('other', $value->getContentHtml());
        $this->assertEquals('one', $value->getContentHtmlOrCurrent(TemplateVersionContentHtmlVO::from($contentHtmlOtherValue))->value());
        $this->assertNotEquals('other', $value->getContentHtmlOrCurrent(TemplateVersionContentHtmlVO::from($contentHtmlOtherValue))->value());
        $value->unsetContentHtml();
        $this->assertEquals('other', $value->getContentHtmlOrCurrent(TemplateVersionContentHtmlVO::from($contentHtmlOtherValue))->value());
        $this->assertNotEquals('one', $value->getContentHtmlOrCurrent(TemplateVersionContentHtmlVO::from($contentHtmlOtherValue))->value());
        $contentTextOneValue = 'one';
        $contentTextOtherValue = 'other';
        $copy = $value->contentText($contentTextOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('one', $value->getContentText());
        $this->assertNotEquals('other', $value->getContentText());
        $this->assertEquals('one', $value->getContentTextOrCurrent(TemplateVersionContentTextVO::from($contentTextOtherValue))->value());
        $this->assertNotEquals('other', $value->getContentTextOrCurrent(TemplateVersionContentTextVO::from($contentTextOtherValue))->value());
        $value->unsetContentText();
        $this->assertEquals('other', $value->getContentTextOrCurrent(TemplateVersionContentTextVO::from($contentTextOtherValue))->value());
        $this->assertNotEquals('one', $value->getContentTextOrCurrent(TemplateVersionContentTextVO::from($contentTextOtherValue))->value());
        $versionOneValue = 1;
        $versionOtherValue = 2;
        $copy = $value->version($versionOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(1, $value->getVersion());
        $this->assertNotEquals(2, $value->getVersion());
        $this->assertEquals(1, $value->getVersionOrCurrent(TemplateVersionVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(2, $value->getVersionOrCurrent(TemplateVersionVersionVO::from($versionOtherValue))->value());
        $value->unsetVersion();
        $this->assertEquals(2, $value->getVersionOrCurrent(TemplateVersionVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(1, $value->getVersionOrCurrent(TemplateVersionVersionVO::from($versionOtherValue))->value());
        $this->assertSame($value, $copy);
    }
}
